  Lemma AStateBlock_open : forall LB m b ioc implb S ds, AStateBlock LB m b ioc implb S ds ->
    exists p j7 j16 j4, In (p, b, SZ_SPCI_STATE) LB /\ rblock_range b SZ_SPCI_STATE
    /\ rw_cells asegs m b (SpcHdrCells (st_hdr S) j7) /\ spc_ok (st_hdr S) /\ spc_vptr (st_hdr S) = AVP_SPCI_STATE
    /\ rw_cells asegs m (b + 32) (AnyExecCells (b + 32) ioc j16)
    /\ rw_cells asegs m (b + 88) [C8 (wz (implb + O_SPC_STORAGE)); C8 (wz implb)]
    /\ APMutex m (b + 104) (st_lk S)
    /\ AFlatBuf LB m (b + 144) (st_fb S) ds
    /\ APCond m (b + 192) 0
    /\ rw_cells asegs m (b + 240)
         [C8 (wz 0); C4 (wz (st_code S)); CB 4 j4; C8 (wz 0); C8 (wz (st_nread S)); C8 (wz (st_nread_bytes S));
          C8 (wz 0); C8 (wz 0); C8 (wz u64max); C8 (wz u64max)]
    /\ (st_code S = STREAM_OK \/ st_code S = STREAM_EOF) /\ 0 <= st_nread S < 2^63 /\ 0 <= st_nread_bytes S < 2^63
    /\ addressable m b SZ_SPCI_STATE.
  Proof.
    intros LB m b ioc implb S ds (p & j7 & j16 & j4 & K). exists p, j7, j16, j4.
    unfold O_ST_EXEC, O_ST_WP_PX, O_ST_MUTEX, O_ST_FB, O_ST_CV, O_ST_OP in K.
    rewrite ?Z.add_0_r in K.
    replace (b + 32 + 56) with (b + 88) in K by lia. replace (b + 32 + 72) with (b + 104) in K by lia.
    replace (b + 32 + 112) with (b + 144) in K by lia. replace (b + 32 + 160) with (b + 192) in K by lia.
    replace (b + 32 + 208) with (b + 240) in K by lia. exact K.
  Qed.
  Lemma AStateBlock_close : forall LB m b ioc implb S ds p j7 j16 j4,
    In (p, b, SZ_SPCI_STATE) LB -> rblock_range b SZ_SPCI_STATE ->
    rw_cells asegs m b (SpcHdrCells (st_hdr S) j7) -> spc_ok (st_hdr S) -> spc_vptr (st_hdr S) = AVP_SPCI_STATE ->
    rw_cells asegs m (b + 32) (AnyExecCells (b + 32) ioc j16) ->
    rw_cells asegs m (b + 88) [C8 (wz (implb + O_SPC_STORAGE)); C8 (wz implb)] ->
    APMutex m (b + 104) (st_lk S) ->
    AFlatBuf LB m (b + 144) (st_fb S) ds ->
    APCond m (b + 192) 0 ->
    rw_cells asegs m (b + 240)
         [C8 (wz 0); C4 (wz (st_code S)); CB 4 j4; C8 (wz 0); C8 (wz (st_nread S)); C8 (wz (st_nread_bytes S));
          C8 (wz 0); C8 (wz 0); C8 (wz u64max); C8 (wz u64max)] ->
    (st_code S = STREAM_OK \/ st_code S = STREAM_EOF) -> 0 <= st_nread S < 2^63 -> 0 <= st_nread_bytes S < 2^63 ->
    addressable m b SZ_SPCI_STATE ->
    AStateBlock LB m b ioc implb S ds.
